import { test, expect } from '@playwright/test';

test.describe('Loading States Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should announce loading state to assistive technology', async ({ page }) => {
    await page.getByRole('button', { name: 'Load Data' }).click();
    const loadingMessage = await page.getByText('Loading, please wait...');

    await expect(loadingMessage).toBeVisible();
    await expect(loadingMessage).toHaveAttribute('aria-live', 'polite');
  });

  test('should remove loading state when data is loaded', async ({ page }) => {
    await page.getByRole('button', { name: 'Load Data' }).click();
    await page.waitForTimeout(2000); // Simulate loading time

    const loadingMessage = await page.getByText('Loading, please wait...');
    await expect(loadingMessage).not.toBeVisible();
    const dataMessage = await page.getByText('Data loaded successfully.');
    await expect(dataMessage).toBeVisible();
    await expect(dataMessage).toHaveAttribute('aria-live', 'assertive');
  });
});
